using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
namespace DoomSNESed {
    public static class ScreenAssets {
        public static readonly int[] Tables={0,0xeff89,0x1ff03d,0x1f5d94,0x1f5dd6,0x1f5e18};
        static byte[] Read(byte[] rom,int entry){int address=GraphicsAssets.Address(rom,entry+2);if((Bin.U16(rom,entry)&0x4000)!=0)return rom.Skip(address).Take(Bin.U16(rom,entry+10)).ToArray();return NativeCompression.Decode(rom,address);}
        static int Pack(Color c){return (c.R>>3)|((c.G>>3)<<5)|((c.B>>3)<<10);}
        static Color Colour(int c){return Color.FromArgb((c&31)*255/31,((c>>5)&31)*255/31,((c>>10)&31)*255/31);}
        public static GraphicReplacement Import(NativeGraphic asset,string path){using(var bitmap=new Bitmap(path)){Bin.Require(bitmap.Width==256&&bitmap.Height==224,"Screen artwork must be exactly 256 x 224 pixels.");var histogram=new Dictionary<int,int>();for(int y=0;y<224;y++)for(int x=0;x<256;x++){int colour=Pack(bitmap.GetPixel(x,y));if(!histogram.ContainsKey(colour))histogram[colour]=0;histogram[colour]++;}var palette=new[]{0}.Concat(histogram.Where(k=>k.Key!=0).OrderByDescending(k=>k.Value).Take(15).Select(k=>k.Key)).ToList();while(palette.Count<16)palette.Add(0);var lookup=new Dictionary<int,byte>();var pixels=new byte[256*224];for(int y=0;y<224;y++)for(int x=0;x<256;x++){int colour=Pack(bitmap.GetPixel(x,y));byte match;if(!lookup.TryGetValue(colour,out match)){Color c=Colour(colour);int distance=int.MaxValue;for(int i=0;i<16;i++){Color q=Colour(palette[i]);int d=(c.R-q.R)*(c.R-q.R)+(c.G-q.G)*(c.G-q.G)+(c.B-q.B)*(c.B-q.B);if(d<distance){distance=d;match=(byte)i;}}lookup[colour]=match;}pixels[y*256+x]=match;}return new GraphicReplacement{Screen=asset.Screen,Width=256,Height=224,Pixels=pixels,Palette=palette.ToArray()};}}
        public static Bitmap Preview(GraphicReplacement asset){var result=new Bitmap(256,224);for(int y=0;y<224;y++)for(int x=0;x<256;x++)result.SetPixel(x,y,Colour(asset.Palette[asset.Pixels[y*256+x]]));return result;}
        public static Bitmap Original(Rom rom,int screen){return OriginalImage(rom.Bytes,screen);}public static Bitmap OriginalImage(byte[] bytes,int screen){int table=RomLayout.At(bytes,Tables[screen]);byte[] definitions=Read(bytes,table);if(screen!=1)definitions=definitions.Concat(Read(bytes,table+16)).ToArray();int mapRow=screen==1?1:2,paletteRow=screen==1?2:3;byte[] map=Read(bytes,table+mapRow*16),palette=Read(bytes,table+paletteRow*16);var bitmap=new Bitmap(256,224);for(int y=0;y<224;y++)for(int x=0;x<256;x++){int entry=Bin.U16(map,((y/8)*32+x/8)*2),tile=entry&1023,px=(entry&0x4000)!=0?7-x%8:x%8,py=(entry&0x8000)!=0?7-y%8:y%8,index=0;for(int plane=0;plane<4;plane++){int p=tile*32+(plane/2)*16+py*2+plane%2;index|=((definitions[p]>>(7-px))&1)<<plane;}int c=Bin.U16(palette,(((entry>>10)&7)*16+index)*2);bitmap.SetPixel(x,y,Colour(c));}return bitmap;}
        static byte[] Flip(byte[] tile,bool horizontal,bool vertical){var result=new byte[32];for(int plane=0;plane<4;plane++)for(int y=0;y<8;y++){byte value=tile[plane/2*16+(vertical?7-y:y)*2+plane%2];if(horizontal){int reversed=0;for(int x=0;x<8;x++)reversed|=((value>>x)&1)<<(7-x);value=(byte)reversed;}result[plane/2*16+y*2+plane%2]=value;}return result;}
        static void Transfer(byte[] bytes,int entry,byte[] payload,List<Section> free,ref int used){if(Read(bytes,entry).SequenceEqual(payload))return;byte[] packed=NativeCompression.Encode(payload);bool compressed=packed.Length<payload.Length;byte[] stored=compressed?packed:payload;int address=GraphicsAssets.Store(bytes,stored,free,ref used);Bin.W16(bytes,entry,compressed?Bin.U16(bytes,entry)&~0x4000:Bin.U16(bytes,entry)|0x4000);Bin.W16(bytes,entry+2,address&65535);bytes[entry+4]=GraphicsAssets.CpuBank(address);bytes[entry+5]=0;Bin.W16(bytes,entry+10,compressed?0:payload.Length);}
        public static void Apply(Rom rom,byte[] bytes,GraphicReplacement asset,List<Section> free,ref int used){Bin.Require((asset.Screen>=1&&asset.Screen<=5)&&asset.Width==256&&asset.Height==224&&asset.Pixels!=null&&asset.Pixels.Length==256*224&&asset.Pixels.All(v=>v<16)&&asset.Palette!=null&&asset.Palette.Length==16&&asset.Palette.All(c=>c>=0&&c<=32767),"Invalid title / logo replacement.");var definitions=new List<byte>();var map=new byte[2048];var tiles=new Dictionary<string,int>();for(int ty=0;ty<28;ty++)for(int tx=0;tx<32;tx++){var tile=new byte[32];for(int y=0;y<8;y++)for(int x=0;x<8;x++){int pixel=asset.Pixels[(ty*8+y)*256+tx*8+x];for(int plane=0;plane<4;plane++)tile[(plane/2)*16+y*2+plane%2]|=(byte)(((pixel>>plane)&1)<<(7-x));}string key=Convert.ToBase64String(tile);int index;if(!tiles.TryGetValue(key,out index)){index=definitions.Count/32;definitions.AddRange(tile);for(int flip=0;flip<4;flip++){string variant=Convert.ToBase64String(Flip(tile,(flip&1)!=0,(flip&2)!=0));if(!tiles.ContainsKey(variant))tiles[variant]=index|((flip&1)!=0?0x4000:0)|((flip&2)!=0?0x8000:0);}}Bin.W16(map,(ty*32+tx)*2,index);}int table=RomLayout.At(bytes,Tables[asset.Screen]);int paletteRow=asset.Screen==1?2:3;byte[] palette=Read(rom.Bytes,table+paletteRow*16);for(int i=0;i<16;i++)Bin.W16(palette,i*2,asset.Palette[i]);if(asset.Screen==1){Transfer(bytes,table,definitions.ToArray(),free,ref used);Transfer(bytes,table+16,map,free,ref used);}else{byte[] all=definitions.ToArray();byte[] first=new byte[Math.Min(16384,all.Length)],second=new byte[Math.Max(32,all.Length-16384)];Buffer.BlockCopy(all,0,first,0,Math.Min(16384,all.Length));if(all.Length>16384)Buffer.BlockCopy(all,16384,second,0,all.Length-16384);Transfer(bytes,table,first,free,ref used);Transfer(bytes,table+16,second,free,ref used);Transfer(bytes,table+32,map,free,ref used);}Transfer(bytes,table+paletteRow*16,palette,free,ref used);}
    }
}



